const darkLogoXml = lightLogoXml.replace('fill="white"', 'fill="#25282F"');

const sizeMap = {
  sm: 112,
  md: 156,
  lg: 210,
} as const;

export function BrandLogo({ size = 'md', subtitle, align = 'left', tone = 'light', plain = false }: BrandLogoProps) {
  const { theme } = useAppTheme();
  const width = sizeMap[size];

  return (
    <View style={[styles.container, align === 'center' ? styles.centered : undefined]}>
      <View
        style={[
          plain ? styles.plainMark : styles.markShell,
          !plain && theme.mode === 'light' ? styles.markShellLight : undefined,
          !plain && theme.mode !== 'light' ? styles.markShellDark : undefined,
        ]}>
        <SvgXml xml={tone === 'dark' ? darkLogoXml : lightLogoXml} width={width} height={(width * 90) / 796} />
      </View>
      {subtitle ? (
        <Text
          style={[
            styles.subtitle,
            { color: theme.colors.muted },
            align === 'center' ? styles.centeredText : undefined,
          ]}>
          {subtitle}
        </Text>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    gap: AppTheme.spacing.xs,
  },
  centered: {
    alignItems: 'center',
  },
  centeredText: {
    textAlign: 'center',
  },
  markShell: {
    borderRadius: AppTheme.radius.md,
    paddingHorizontal: AppTheme.spacing.sm,
    paddingVertical: AppTheme.spacing.xs,
  },
  markShellLight: {
    backgroundColor: 'rgba(227, 30, 36, 0.06)',
  },
  markShellDark: {
    backgroundColor: 'rgba(255, 255, 255, 0.03)',
  },
  plainMark: {
    paddingHorizontal: 0,
    paddingVertical: 0,
  },
  subtitle: {
    fontFamily: Typography.body,
    fontSize: 12,
    lineHeight: 17,
  },
});
